163	 * Deliberately no count. This category exists for one measured browser
164	 * behavior: a page fetches an asset, re-renders while that fetch is in flight,
165	 * starts an identical fetch, and the browser cancels one of the two. Which of
166	 * them the browser cancels, and how many times it happens in a given run, is
167	 * scheduling — pinning a count would pin a race. What is pinned instead is the
168	 * identity of the request that may be cancelled, and admission still requires
169	 * the corroboration below on every single instance.
170	 */
171	export type WitnessCancelledDuplicateFetchCategoryEntry = {
172		method: string;
173		path: string;
174		/** The browser's own cancellation reason, matched exactly. */
175		reason: string;
