398	function record(value: unknown, label: string): Record<string, unknown> {
399		if (value === null || typeof value !== 'object' || Array.isArray(value))
400			throw new Error(`Witness real-app ${label} must be an object`);
401		return value as Record<string, unknown>;
402	}
