404	function sha256Digest(value: unknown): value is string {
405		return typeof value === 'string' && value.length === 64;
406	}
407	
408	function sortedUniqueStrings(values: unknown): values is string[] {
409		return (
410			Array.isArray(values) &&
411			values.every((value) => typeof value === 'string') &&
412			new Set(values).size === values.length &&
413			values.join('\n') === [...values].sort().join('\n')
414		);
415	}
416	
417	function validServiceWorkerTelemetry(value: unknown): value is WitnessServiceWorkerTelemetry {
418		const telemetry = value as WitnessServiceWorkerTelemetry;
419		return (
420			telemetry?.state === 'ready' &&
421			telemetry.registration?.scriptPath === '/sw.js' &&
422			telemetry.registration.scope === '/' &&
423			telemetry.registration.active === 'activated' &&
424			(telemetry.controller === 'activated' || telemetry.controller === null) &&
425			sortedUniqueStrings(telemetry.cacheNames) &&
426			telemetry.cacheNames.length === 1 &&
427			Array.isArray(telemetry.cacheEntries) &&
428			telemetry.cacheEntries.length === 1 &&
429			telemetry.cacheEntries[0]?.name === telemetry.cacheNames[0] &&
430			sortedUniqueStrings(telemetry.cacheEntries[0].paths) &&
431			telemetry.cacheEntries[0].paths.length > 0 &&
432			telemetry.cacheEntries[0].paths.every((path) => path.startsWith('/')) &&
433			Array.isArray(telemetry.workerEvents)
434		);
