536						!sha256Digest(served.phonecatImageTransition.detailSha256) ||
537						!served.phonecatImageTransition.defaultImage.startsWith('img/phones/') ||
538						!served.phonecatImageTransition.nonDefaultImage.startsWith('img/phones/') ||
539						served.phonecatImageTransition.defaultImage ===
540							served.phonecatImageTransition.nonDefaultImage ||
541						served.phonecatImageTransition.hover !== 'genuine-thumbnail-mouseover' ||
542						served.phonecatImageTransition.transition !== 'genuine-ng-click' ||
543						served.phonecatImageTransition.heroVisibility !== 'genuine-hover'
544					: served.phonecatImageTransition?.state !== 'not-applicable';
545			const observerFinalizationDiffers =
546				run.observerFinalization?.state !== 'target-closed' ||
547				run.observerFinalization.detach !== 'owned-detach-complete' ||
548				run.observerFinalization.pageClose !== 'owned-page-close-complete' ||
549				!Array.isArray(run.observerFinalization.workerEvents);
550			const lifecycle =
551				run.offlineEvidence.state === 'react-shell-rendered-state-reset'
552					? run.offlineEvidence.lifecycle
553					: undefined;
554			const expectedCacheName =
555				run.lane === 'baseline'
556					? 'webpack-offline:versionless-deterministic'
557					: 'versionless-react-vite8-553cd1cc611a0851b1978bbc041ef2f8c7b9fbbd3fdd9bb68274f29364987cdc';
558			const lifecycleDiffers =
559				run.app === 'react-boilerplate'
560					? lifecycle?.state !== 'ready-online-reload-controlled-offline-reset' ||
561						!validServiceWorkerTelemetry(lifecycle.ready) ||
562						!validServiceWorkerTelemetry(lifecycle.controlled) ||
563						lifecycle.controlled.controller !== 'activated' ||
564						lifecycle.ready.cacheNames[0] !== expectedCacheName ||
565						canonicalize(lifecycle.ready.cacheEntries) !==
566							canonicalize(lifecycle.controlled.cacheEntries) ||
567						!sortedUniqueStrings(lifecycle.onlineStaticPaths) ||
568						!lifecycle.onlineStaticPaths.includes('/sw.js') ||
569						lifecycle.ready.cacheEntries[0]!.paths.some(
570							(path) =>
571								path !== '/__offline_webpack__data' &&
572								!lifecycle.onlineStaticPaths.includes(path),
573						) ||
574						lifecycle.offlineServerRequests !== 0
575					: lifecycle !== undefined;
576			if (
577				run.interactions.some((interaction) => interaction.kind === 'drag') &&
578				!(WITNESS_REAL_APP_DRAG_SURFACES as readonly string[]).includes(run.app)
579			)
580				throw new Error('Witness real-app drag must remain not-tested');
581			if (
582				!expected.delete(key) ||
583				run.result !== 'pass' ||
584				run.successfulNonLoopback !== 0 ||
585				!Array.isArray(run.interactions) ||
586				run.interactions.length === 0 ||
587				!Array.isArray(run.assertions) ||
588				run.assertions.length === 0 ||
589				servedStaticDiffers ||
590				legacyMainPrecacheDiffers ||
591				phonecatOrderingDiffers ||
592				phonecatImageTransitionDiffers ||
593				observerFinalizationDiffers ||
594				lifecycleDiffers ||
595				run.cleanPage !== true ||
596				(run.app === 'react-boilerplate'
597					? run.offlineEvidence?.state !== 'react-shell-rendered-state-reset' ||
598						run.offlineEvidence.shellRendered !== true ||
599						run.offlineEvidence.usernameReset !== true ||
600						run.offlineEvidence.repositoriesReset !== true ||
601						run.offlineEvidence.apiResponseCaching !== 'not-claimed' ||
602						run.offlineEvidence.reduxPersistence !== 'not-implemented' ||
603						run.offlineEvidence.priorResultPersistence !== 'not-implemented' ||
604						run.offlineEvidence.harnessFulfillment !==
605							'synthetic-github-route-online-only' ||
606						run.offlineEvidence.serviceWorkerEvidence?.source !== 'canonical-t060' ||
607						run.offlineEvidence.serviceWorkerEvidence.receiptPath !==
608							'evidence/runs/react-boilerplate-v4-composed/t060-run.json' ||
609						run.offlineEvidence.serviceWorkerEvidence.canonicalDigest !==
610							'52400147929220935a9ebe47a16c8dff50b5c28e9d51c930d000c99c2bdc8a21' ||
611						run.offlineEvidence.serviceWorkerEvidence.newProof !== false
612					: run.offlineEvidence?.state !== 'not-applicable') ||
613				run.semanticDigest !==
614					sha256(
615						canonicalize({
616							app: run.app,
617							framework: run.framework,
618							lane: run.lane,
619							interactions: run.interactions,
620							assertions: run.assertions,
621							routes: run.routes,
622							trackedEvents: run.trackedEvents,
623							witnessRecord: run.witnessRecord,
624							cleanPage: run.cleanPage,
625							offlineEvidence: run.offlineEvidence,
626							servedStatic: run.servedStatic,
627							observerFinalization: run.observerFinalization,
628							successfulNonLoopback: run.successfulNonLoopback,
629						}),
630					)
631			)
632				throw new Error(`Witness real-app run differs: ${key}`);
633			const pair = `${run.app}:${run.lane}`;
634			const prior = semanticPasses.get(pair);
635			if (prior !== undefined && prior !== run.semanticDigest)
636				throw new Error(`Witness real-app repeated pass differs: ${pair}`);
637			semanticPasses.set(pair, run.semanticDigest);
638			for (const interaction of run.interactions) {
639				gestures.add(interaction.kind);
640			}
641		}
642		if (
643			expected.size !== 0 ||
644			[...gestures].sort().join(',') !== 'click,drag,hover,press,scroll,type'
645		)
